package fr.xerion.xrnhud.mixin;
import org.spongepowered.asm.mixin.*;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;import fr.xerion.xrnhud.*;
@Mixin(net.minecraft.client.render.entity.ItemEntityRenderer.class) public abstract class ItemScaleDropMixin {
 @Inject(method="updateRenderState(Lnet/minecraft/entity/ItemEntity;Lnet/minecraft/client/render/entity/state/ItemEntityRenderState;F)V",at=@At("RETURN"),require=1)private void xrn$state(net.minecraft.entity.ItemEntity entity,net.minecraft.client.render.entity.state.ItemEntityRenderState state,float delta,CallbackInfo ci){((DroppedItemScale)(Object)state).xrn$dropScale(TailleObjets.auSol(entity.getStack()));}
 @Inject(method="render(Lnet/minecraft/client/render/entity/state/ItemEntityRenderState;Lnet/minecraft/client/util/math/MatrixStack;Lnet/minecraft/client/render/command/OrderedRenderCommandQueue;Lnet/minecraft/client/render/state/CameraRenderState;)V",at=@At("HEAD"),require=1)private void xrn$scale(net.minecraft.client.render.entity.state.ItemEntityRenderState state,net.minecraft.client.util.math.MatrixStack matrices,net.minecraft.client.render.command.OrderedRenderCommandQueue queue,net.minecraft.client.render.state.CameraRenderState camera,CallbackInfo ci){float f=((DroppedItemScale)(Object)state).xrn$dropScale();matrices.push();matrices.scale(f,f,f);}
 @Inject(method="render(Lnet/minecraft/client/render/entity/state/ItemEntityRenderState;Lnet/minecraft/client/util/math/MatrixStack;Lnet/minecraft/client/render/command/OrderedRenderCommandQueue;Lnet/minecraft/client/render/state/CameraRenderState;)V",at=@At("RETURN"),require=1)private void xrn$restore(net.minecraft.client.render.entity.state.ItemEntityRenderState state,net.minecraft.client.util.math.MatrixStack matrices,net.minecraft.client.render.command.OrderedRenderCommandQueue queue,net.minecraft.client.render.state.CameraRenderState camera,CallbackInfo ci){matrices.pop();}
}
